mapper.select:
SELECT USER_ID,
       EMAIL,
       COMPANY_CODE
FROM TB_USER_MASTER
WHERE USER_ID = #{userId}
  AND EMAIL    = #{email}

mapper.update:
UPDATE TB_LOGIN_MASTER
SET PASSWORD = #{password},
    UPDATED_BY = 'SYSTEM',
    UPDATE_DATE = SYSDATE
WHERE COMPANY_CODE = #{companyCode}
  AND USER_ID = #{userId}
